825	    write_file(f_abc, abc);
826	    write_file(f_empty, empty);
827	
828	    const std::vector<fs::path> batch{f_a, f_abc, f_empty};
829	    const Digest trusted = root_of(batch);
830	    const Digest other_root = root_of({f_a, f_abc});
831	
832	    auto reject = [&](const MerkleProof& p, const Digest& root,
833	                      const Digest& leaf, std::string_view what) {
834	        const MerkleVerifyResult v =
835	            branchaudit::merkle_verify_proof(p, root, leaf);
836	        check(!v.ok() && !v.valid && !v.error.empty(), what);
837	    };
838	
839	    // 条件 1：内容叶子与证明叶子不符。
840	    {
841	        const MerkleProof p =
842	            branchaudit::merkle_proof_file(batch, 0).proof;
843	        reject(p, trusted, leaf_bytes(abc),
844	               "wrong content leaf (different file content) is rejected");
845	        // 普通文件摘要（无 0x00 前缀）不能替代叶子摘要。
846	        branchaudit::Sha256 plain;
847	        plain.update(reinterpret_cast<const unsigned char*>(a.data()),
848	                     a.size());
849	        reject(p, trusted, plain.final(),
850	               "plain hash digest without the 0x00 leaf prefix is rejected");
851	    }
852	
853	    // 条件 2：证明自报的根与可信根不符——即使证明内部自洽，换另一批次的
854	    // 可信根也必须失败，不能拿 proof.root 充当信任依据。
855	    {
856	        const MerkleProof p =
857	            branchaudit::merkle_proof_file(batch, 0).proof;
858	        reject(p, other_root, leaf_bytes(a),
859	               "internally consistent proof fails against another batch's "
860	               "trusted root");
861	        Digest fake_trusted = trusted;
862	        fake_trusted[0] ^= 0x01;
863	        reject(p, fake_trusted, leaf_bytes(a),
864	               "proof fails when the trusted root differs by one bit");
865	    }
866	
867	    // 结构：空批次没有成员。
868	    {
869	        MerkleProof p;
870	        p.leaf_count = 0;
871	        p.leaf_index = 0;
872	        p.leaf = leaf_bytes(a);
873	        p.root = trusted;
874	        reject(p, trusted, leaf_bytes(a),
875	               "leaf_count 0 (empty batch) has no members");
876	    }
877	
878	    // 结构：位置越界。
879	    {
880	        MerkleProof p =
881	            branchaudit::merkle_proof_file(batch, 0).proof;
882	        p.leaf_index = 3;
883	        reject(p, trusted, leaf_bytes(a),
884	               "leaf_index equal to leaf_count is rejected");
885	        p.leaf_index = 100;
886	        reject(p, trusted, leaf_bytes(a),
887	               "leaf_index beyond leaf_count is rejected");
888	        p = branchaudit::merkle_proof_file({f_a}, 0).proof;
889	        p.leaf_index = 1;
890	        reject(p, root_of({f_a}), leaf_bytes(a),
891	               "single-file batch rejects index other than 0");
892	    }
893	
894	    // 结构：单文件批次带多余兄弟、空兄弟却是多文件计数。
895	    {
896	        MerkleProof p =
897	            branchaudit::merkle_proof_file({f_a}, 0).proof;
898	        p.siblings.push_back({MerkleSibling::Side::left, leaf_bytes(abc)});
899	        reject(p, root_of({f_a}), leaf_bytes(a),
900	               "single-file batch accepts only an empty sibling list");
901	    }
902	
903	    // 结构：兄弟方向错误（即使换成“折叠能得到某个摘要”的内容也不行）。
904	    {
905	        MerkleProof p =
906	            branchaudit::merkle_proof_file(batch, 0).proof;
907	        // 位置 0 第一层要求 right 兄弟：翻成 left 必须失败。
908	        p.siblings[0].side = MerkleSibling::Side::left;
909	        reject(p, trusted, leaf_bytes(a),
910	               "wrong sibling side is rejected regardless of digest values");
911	    }
912	
913	    // 结构：缺少一个必要兄弟。
914	    {
915	        MerkleProof p =
916	            branchaudit::merkle_proof_file(batch, 0).proof;
917	        p.siblings.pop_back();
918	        reject(p, trusted, leaf_bytes(a),
919	               "a missing required sibling is rejected");
920	    }
921	
922	    // 结构：多出一个兄弟。
923	    {
924	        MerkleProof p =
925	            branchaudit::merkle_proof_file(batch, 0).proof;
926	        p.siblings.push_back({MerkleSibling::Side::left, leaf_bytes(empty)});
927	        reject(p, trusted, leaf_bytes(a),
928	               "an extra sibling beyond the root is rejected");
929	    }
930	
931	    // 结构：兄弟从叶子向根的次序被调换（两者侧向恰好与另一层相同，
932	    // 数量不变、每一项单独看都是 left/right，仍必须失败）。
933	    {
934	        MerkleProof p =
935	            branchaudit::merkle_proof_file(batch, 0).proof;
936	        // 位置 0、三文件：两层都要求 right，交换两项只错次序。
937	        check(p.siblings.size() == 2 &&
938	                      p.siblings[0].side == MerkleSibling::Side::right &&
939	                      p.siblings[1].side == MerkleSibling::Side::right,
940	              "fixture: 3-file index 0 has two right-side siblings");
941	        std::swap(p.siblings[0], p.siblings[1]);
942	        reject(p, trusted, leaf_bytes(a),
