944	    }
945	
946	    // 结构：兄弟摘要被篡改——方向/数量/次序都对，但折叠不到可信根。
947	    {
948	        MerkleProof p =
949	            branchaudit::merkle_proof_file(batch, 0).proof;
950	        p.siblings[0].digest = leaf_bytes(bytes_of("totally different"));
951	        reject(p, trusted, leaf_bytes(a),
952	               "tampered sibling digest fails the fold into the root");
953	    }
954	
955	    // 条件 3 的独立攻击：把 proof.root 改成可信根，叶子与根字段都对，
956	    // 但兄弟链属于另一结构——折叠结果不等于可信根。
957	    {
958	        MerkleProof p =
959	            branchaudit::merkle_proof_file(batch, 0).proof;
960	        p.siblings.clear();
961	        // 声称 3 个叶子却不给兄弟，同时 root 伪装成可信根。
962	        p.root = trusted;
963	        reject(p, trusted, leaf_bytes(a),
964	               "missing siblings with a forged root field are rejected");
965	    }
966	
967	    // 提升层不得要求补记录：删掉的若是“有兄弟的层”才失败；而把一个
968	    // 本应省略的提升层补一条记录，同样属于多出项，必须失败。
969	    {
970	        // 三文件、位置 2：第一层提升（无记录），第二层一个 left 兄弟。
971	        const MerkleProof real =
972	            branchaudit::merkle_proof_file(batch, 2).proof;
973	        check(real.siblings.size() == 1,
974	              "fixture: promoted index carries one sibling");
975	        MerkleProof padded = real;
976	        padded.siblings.insert(
977	            padded.siblings.begin(),
978	            MerkleSibling{MerkleSibling::Side::right, leaf_bytes(abc)});
979	        reject(padded, trusted, leaf_bytes(empty),
980	               "padding an omitted promotion level with a record is rejected");
981	    }
982	
983	    // 非法 side 枚举值（调用方自行构造结构时可能出现）。
984	    {
985	        MerkleProof p =
986	            branchaudit::merkle_proof_file(batch, 0).proof;
987	        p.siblings[0].side = static_cast<MerkleSibling::Side>(99);
988	        reject(p, trusted, leaf_bytes(a),
989	               "an invalid sibling side value is rejected");
990	    }
991	
992	    // 失败时同样不打印、不退出，并给出非空原因。
993	    {
994	        const MerkleProof p =
995	            branchaudit::merkle_proof_file(batch, 0).proof;
996	        std::stringstream cap_out, cap_err;
997	        auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
998	        auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
999	        const MerkleVerifyResult v =
1000	            branchaudit::merkle_verify_proof(p, other_root, leaf_bytes(a));
1001	        std::cout.rdbuf(old_out);
1002	        std::cerr.rdbuf(old_err);
1003	        check(!v.ok() && !v.error.empty(),
1004	              "cross-branch verify fails with a reason");
1005	        check(cap_out.str().empty() && cap_err.str().empty(),
1006	              "verify library: prints nothing on failure");
1007	    }
