1027	    const fs::path f_mar = tmp.root / "report-mar.bin";
1028	    write_file(f_jan, jan);
1029	    write_file(f_feb, feb);
1030	    write_file(f_mar, mar);
1031	
1032	    const std::vector<fs::path> batch{f_jan, f_feb, f_mar};
1033	
1034	    // 可信根独立于证明保存：对同一批次另行计算，而不是取 proof.root。
1035	    const Digest trusted = root_of(batch);
1036	    // 第三个文件（位置 2）按现有规则计算的内容叶子 SHA-256(0x00 || content)。
1037	    const Digest mar_leaf = leaf_bytes(mar);
1038	
1039	    const MerkleProofResult pr =
1040	        branchaudit::merkle_proof_file(batch, /*leaf_index=*/2);
1041	    check(pr.ok(), std::string("claimed-numbers fixture proof: ") + pr.error);
1042	    const MerkleProof proof = pr.proof;
1043	
1044	    // 夹具形状：位置 2 在三条目批次首层是奇数末节点，原样提升、不补兄弟
1045	    // 记录；只在上层记录一个 left 兄弟，摘要为前两份内容叶子的父节点。
1046	    check(proof.leaf_count == 3 && proof.leaf_index == 2,
1047	          "claimed-numbers fixture: proof self-reports count 3, index 2");
1048	    check(proof.leaf == mar_leaf,
1049	          "claimed-numbers fixture: proof leaf is the third file's 0x00 leaf");
1050	    check(proof.root == trusted,
1051	          "claimed-numbers fixture: generated root equals the independently "
1052	          "computed trusted root");
1053	    check(proof.siblings.size() == 1 &&
1054	                  proof.siblings[0].side == MerkleSibling::Side::left &&
1055	                  proof.siblings[0].digest ==
1056	                      branchaudit::merkle_parent(leaf_bytes(jan), leaf_bytes(feb)),
1057	          "claimed-numbers fixture: odd last node promoted without a sibling; "
1058	          "a single left sibling remains at the upper level");
1059	
1060	    // 原证明在独立可信根与第三文件内容叶子下通过：valid 为真、error 为空。
1061	    {
1062	        const MerkleVerifyResult v =
1063	            branchaudit::merkle_verify_proof(proof, trusted, mar_leaf);
1064	        check(v.ok() && v.valid && v.error.empty(),
1065	              "original proof (count=3, index=2) verifies: valid is true and "
1066	              "error is empty");
1067	    }
1068	
1069	    // 只改证明自报的两个数字：leaf_count 3→2、leaf_index 2→1；根、叶子、
1070	    // 兄弟摘要与兄弟方向全部保持原样。
1071	    MerkleProof altered = proof;
1072	    altered.leaf_count = 2;
1073	    altered.leaf_index = 1;
1074	    check(altered.root == proof.root && altered.leaf == proof.leaf &&
1075	                  altered.siblings.size() == proof.siblings.size() &&
1076	                  altered.siblings[0].side == proof.siblings[0].side &&
1077	                  altered.siblings[0].digest == proof.siblings[0].digest,
1078	          "altered proof differs from the original only in the two claimed "
1079	          "numbers");
1080	
1081	    // 位置 2 在三条目批次的首层被原样提升（无兄弟记录），其兄弟路径形状与
1082	    // “两条目批次的位置 1”完全相同：同一份根、叶子与兄弟记录对两组声明都
1083	    // 自洽。这种“声明数字改变、证明仍成立”的输入不能被误判为损坏。
1084	    {
1085	        const MerkleVerifyResult v =
1086	            branchaudit::merkle_verify_proof(altered, trusted, mar_leaf);
1087	        check(v.ok() && v.valid && v.error.empty(),
1088	              "altered claims (count=2, index=1) still verify against the same "
1089	              "trusted root and content leaf: valid is true, error is empty");
1090	    }
1091	
1092	    // 通过不认证这两个数字：随可信根独立保存的批次事实仍是 3 个条目、
1093	    // 位置 2。真正要确认批次大小/位置的调用方必须另行比对证明自报数字，
1094	    // 校验通过代替不了它——原证明的声明与独立事实相符，改写后的不符。
1095	    const auto claims_match_independent_fact = [](const MerkleProof& p) {
1096	        return p.leaf_count == 3 && p.leaf_index == 2;
1097	    };
1098	    check(claims_match_independent_fact(proof),
1099	          "the genuine proof's claims match the independently stored batch "
1100	          "fact (count 3, index 2)");
1101	    check(!claims_match_independent_fact(altered),
1102	          "the altered claims differ from the independent fact even though "
1103	          "verify passes: success is not a certification of count or position");
1104	
1105	    auto reject = [&](const MerkleProof& p, const Digest& root,
1106	                      const Digest& leaf, std::string_view what) {
1107	        const MerkleVerifyResult v =
1108	            branchaudit::merkle_verify_proof(p, root, leaf);
1109	        check(!v.ok() && !v.valid && !v.error.empty(), what);
1110	    };
1111	
1112	    // 拒绝边界 1：在改写后的证明上只把位置 1→0，其余输入不动。两条目批次
1113	    // 的位置 0 在首层需要 right 兄弟，而保留下来的唯一兄弟是 left——声明
1114	    // 位置与保留兄弟方向不符，必须失败。这守住位置结构检查，防止为了让
1115	    // “等价改写”通过而放松方向核对。
1116	    {
1117	        MerkleProof wrong_pos = altered;
1118	        wrong_pos.leaf_index = 0;
1119	        reject(wrong_pos, trusted, mar_leaf,
1120	               "altered proof with only the position changed to 0 is rejected: "
1121	               "a 2-leaf position 0 requires a right sibling, conflicting with "
1122	               "the retained left sibling");
1123	    }
1124	
1125	    // 拒绝边界 2：仍然自洽的改写证明换用不匹配的可信根也必须失败；声明
1126	    // 数字的等价性不能绕过可信根核对。
1127	    {
1128	        // 顺序不同的另一份批次（内容相同、排列改变）产生另一个根。
1129	        const Digest reordered_root = root_of({f_jan, f_mar, f_feb});
1130	        check(reordered_root != trusted,
1131	              "fixture: reordered batch yields a different root");
1132	        reject(altered, reordered_root, mar_leaf,
1133	               "altered proof fails against another batch's trusted root");
1134	        Digest flipped = trusted;
1135	        flipped[0] ^= 0x01;
1136	        reject(altered, flipped, mar_leaf,
1137	               "altered proof fails against a trusted root differing by one "
1138	               "bit");
1139	    }
1140	
1141	    // 拒绝边界 3：同一份改写证明配另一份内容的叶子（同样带单个 0x00
1142	    // 前缀）也必须失败；声明数字的等价性不能绕过内容核对。
1143	    {
1144	        reject(altered, trusted, leaf_bytes(jan),
1145	               "altered proof fails with another content's 0x00-prefixed leaf");
1146	        // 普通文件摘要（无 0x00 前缀）同样不能借等价改写混入。
1147	        branchaudit::Sha256 plain;
1148	        plain.update(reinterpret_cast<const unsigned char*>(mar.data()),
1149	                     mar.size());
1150	        reject(altered, trusted, plain.final(),
1151	               "altered proof rejects a plain file digest without the 0x00 "
1152	               "leaf prefix");
1153	    }
1154	}
1155	
1156	// ---- 64 位计数边界：纯结构推导，不按 leaf_count 分配内存 --------------------
1157	
1158	// 沿 (leaf_count, leaf_index) 计算生成端会记录的兄弟数与各层期望侧向，
1159	// 用独立的一份循环模拟证明形状（不调用生成接口，也不需要真实文件）。
1160	struct ShapeStep {
1161	    MerkleSibling::Side side;
1162	};
1163	std::vector<ShapeStep> expected_shape(std::uint64_t leaf_count,
1164	                                      std::uint64_t leaf_index) {
1165	    std::vector<ShapeStep> steps;
1166	    std::uint64_t n = leaf_count;
1167	    std::uint64_t pos = leaf_index;
1168	    while (n > 1) {
1169	        const bool promoted = (pos % 2 == 0) && (pos == n - 1);
1170	        if (!promoted) {
1171	            steps.push_back({(pos % 2 == 0) ? MerkleSibling::Side::right
1172	                                            : MerkleSibling::Side::left});
1173	        }
1174	        pos /= 2;
1175	        n -= n / 2;
1176	    }
1177	    return steps;
1178	}
1179	
1180	void test_verify_uint64_limits() {
1181	    // 沿 (leaf_count, leaf_index) 按形状构造一份结构自洽的证明：兄弟摘要
1182	    // 全部取零，折叠结果与 root 字段、可信根保持一致，因此通过与否只取
1183	    // 决于结构推导是否无回绕、必定终止（不依赖真实文件或巨大内存）。
1184	    auto build_shaped_proof = [](std::uint64_t leaf_count,
1185	                                 std::uint64_t leaf_index,
1186	                                 const std::vector<ShapeStep>& shape) {
1187	        MerkleProof p;
1188	        p.leaf_count = leaf_count;
1189	        p.leaf_index = leaf_index;
1190	        Digest leaf{};
1191	        leaf[31] = 0x7f;
1192	        p.leaf = leaf;
1193	        Digest node = leaf;
1194	        for (const ShapeStep& st : shape) {
1195	            const Digest sib{};
1196	            if (st.side == MerkleSibling::Side::right) {
1197	                p.siblings.push_back({MerkleSibling::Side::right, sib});
1198	                node = branchaudit::merkle_parent(node, sib);
1199	            } else {
1200	                p.siblings.push_back({MerkleSibling::Side::left, sib});
1201	                node = branchaudit::merkle_parent(sib, node);
1202	            }
1203	        }
1204	        p.root = node;
1205	        return std::pair<MerkleProof, Digest>{p, node};
1206	    };
1207	
1208	    // leaf_count = UINT64_MAX（最大可表示的合法计数，奇数），位置 0：
1209	    // 位置 0 每层都是偶数下标且永不等于本层末下标，因此每层都有 right
1210	    // 兄弟。层数恰为 64：反复 ceil(n/2) 把 2^64-1 经 63 次提升变为 2，
1211	    // 第 64 层变为 1。结构循环必须走完 64 层、消费 64 项后终止。
1212	    constexpr std::uint64_t kMax = ~std::uint64_t{0};
1213	    {
1214	        const std::vector<ShapeStep> shape = expected_shape(kMax, 0);
1215	        check(shape.size() == 64,
1216	              "UINT64_MAX leaves index 0: exactly 64 right-sibling levels");
1217	        for (const ShapeStep& st : shape) {
1218	            check(st.side == MerkleSibling::Side::right,
1219	                  "UINT64_MAX leaves index 0: every sibling is on the right");
1220	        }
1221	
1222	        const auto [p, folded] = build_shaped_proof(kMax, 0, shape);
1223	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1224	              "UINT64_MAX leaves: structurally exact proof verifies "
1225	              "deterministically without wraparound");
1226	
1227	        // 可信根差一位：必须在完整走完 64 层结构核对后才失败于根比对。
1228	        Digest other = folded;
1229	        other[0] ^= 0x80;
1230	        check(!branchaudit::merkle_verify_proof(p, other, p.leaf).ok(),
1231	              "UINT64_MAX leaves: wrong trusted root rejected after the full "
1232	              "64-level traversal");
1233	
1234	        // 少最后一个兄弟：第 64 层缺项必须被发现，不能误判通过。
1235	        MerkleProof short_proof = p;
1236	        short_proof.siblings.pop_back();
1237	        check(!branchaudit::merkle_verify_proof(short_proof, folded, p.leaf).ok(),
1238	              "UINT64_MAX leaves: a missing sibling at the final level is "
1239	              "detected");
1240	
1241	        // 多一个兄弟：按形状只该有 64 项。
1242	        MerkleProof long_proof = p;
1243	        long_proof.siblings.push_back({MerkleSibling::Side::left, Digest{}});
1244	        check(!branchaudit::merkle_verify_proof(long_proof, folded, p.leaf).ok(),
1245	              "UINT64_MAX leaves: a trailing extra sibling is rejected");
1246	    }
1247	
1248	    // 位置取最大合法值 UINT64_MAX-1（偶数，恰为奇数层的末下标）：第 0 层
1249	    // 原样提升、不产生兄弟记录；之后每层节点数均为偶数、该位置都是奇数
1250	    // 下标，故共 63 条 left 兄弟。重点验证：首层省略提升记录不会被误判为
1251	    // 缺项，且奇数下标分支在极限值上不回绕。
1252	    {
1253	        const std::uint64_t last = kMax - 1;
1254	        const std::vector<ShapeStep> shape = expected_shape(kMax, last);
1255	        check(shape.size() == 63,
1256	              "UINT64_MAX leaves index UINT64_MAX-1: 63 records (level 0 "
1257	              "promoted without a sibling)");
1258	        for (const ShapeStep& st : shape) {
1259	            check(st.side == MerkleSibling::Side::left,
1260	                  "UINT64_MAX leaves index UINT64_MAX-1: every recorded "
1261	                  "sibling is on the left");
1262	        }
1263	
1264	        const auto [p, folded] = build_shaped_proof(kMax, last, shape);
1265	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1266	              "UINT64_MAX leaves at the last even position verifies without "
1267	              "integer wraparound and without a padded promotion record");
1268	    }
1269	
1270	    // leaf_index == leaf_count 是越界（即使两者都是最大可表示值）。
1271	    {
1272	        MerkleProof p;
1273	        p.leaf_count = kMax;
1274	        p.leaf_index = kMax;
1275	        p.leaf = Digest{};
1276	        check(!branchaudit::merkle_verify_proof(p, Digest{}, Digest{}).ok(),
1277	              "UINT64_MAX: leaf_index equal to leaf_count is out of range");
1278	    }
1279	
1280	    // 2 的幂边界 leaf_count = 2^63，末位置 2^63-1（奇数）：每层都有 left
1281	    // 兄弟、没有任何提升省略，共 63 条；这是“全左、无省略”的极限形状，
1282	    // 与前一块“首层省略”互为对照，两条路径上的下标推导都不得回绕。
1283	    {
1284	        constexpr std::uint64_t kPow2 = UINT64_C(1) << 63;
1285	        const std::uint64_t last = kPow2 - 1;
1286	        const std::vector<ShapeStep> shape = expected_shape(kPow2, last);
1287	        check(shape.size() == 63,
1288	              "2^63 leaves at the last position: 63 levels, none omitted");
1289	        for (const ShapeStep& st : shape) {
1290	            check(st.side == MerkleSibling::Side::left,
1291	                  "2^63 leaves last position: every sibling is on the left");
1292	        }
1293	        const auto [p, folded] = build_shaped_proof(kPow2, last, shape);
1294	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1295	              "2^63 leaves: structurally exact proof verifies deterministically");
1296	    }
1297	}
1298	
1299	// ---- 大文件：流式读取、尾部敏感 -------------------------------------------
1300	
1301	void test_large_files() {
1302	    TempArea tmp("large");
1303	    const std::vector<unsigned char> big = fill_a(200000);
1304	    const std::vector<unsigned char> pat = pattern(200000);
1305	    const fs::path f_big = tmp.root / "a200000.bin";
1306	    const fs::path f_pat = tmp.root / "pattern200000.bin";
1307	    write_file(f_big, big);
1308	    write_file(f_pat, pat);
1309	
1310	    check(hex_of(root_of({f_big})) ==
1311	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
1312	          "single large file leaf (streaming)");
1313	    check(hex_of(root_of({f_big, f_pat})) ==
1314	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
1315	          "root [big, pattern]");
1316	    check(hex_of(root_of({f_pat, f_big})) ==
1317	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
1318	          "root [pattern, big] differs under reversal");
1319	
1320	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
1321	    std::vector<unsigned char> tail = big;
1322	    tail.back() = static_cast<unsigned char>('b');
1323	    const fs::path f_tail = tmp.root / "a200000tail.bin";
1324	    write_file(f_tail, tail);
1325	    check(hex_of(root_of({f_tail})) ==
1326	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
1327	          "large file: changing last byte changes leaf/root");
1328	    check(root_of({f_tail}) != root_of({f_big}),
1329	          "large file: tail change is detected");
1330	}
1331	
1332	}  // namespace
1333	
1334	int main(int argc, char** argv) {
1335	    fault_test::ensure_fault_preloaded(argc, argv);
1336	
1337	    test_empty_batch();
1338	    test_leaf_rule();
1339	    test_parent_rule();
1340	    test_file_batches();
1341	    test_relative_paths();
1342	    test_failures();
1343	    if (fault_test::kFaultInjectionAvailable) {
1344	        test_io_failures();
1345	    } else {
1346	        // 平台无 LD_PRELOAD//proc 故障注入支持（如 macOS）：明确报告
1347	        // 跳过，不计入已通过检查。
1348	        ++g_skipped;
1349	        std::cout << "SKIP: unopenable-leaf and mid-read-error checks "
1350	                     "(fault injection not supported on this platform)\n";
1351	    }
1352	    test_large_files();
1353	    test_proofs();
1354	    test_verify_success();
1355	    test_verify_failures();
1356	    test_verify_claimed_numbers();
1357	    test_verify_uint64_limits();
1358	
1359	    if (g_failures == 0) {
1360	        std::cout << "all " << g_checks << " merkle regression checks passed";
1361	        if (g_skipped > 0) {
1362	            std::cout << " (" << g_skipped << " platform-specific check group"
1363	                         " skipped, not verified)";
1364	        }
1365	        std::cout << '\n';
1366	        return 0;
1367	    }
1368	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
1369	    return 1;
1370	}
