#ifdef BRANCHAUDIT_CLI
// 真正执行 prove 命令并取回其标准输出的全部字节（含末尾换行），使“读取
// 完整接受命令输出”经由真实子进程端到端固定，而不是只靠测试内的序列化。
std::string shell_quote(std::string_view s) {
    std::string out = "'";
    for (char c : s) {
        if (c == '\'') {
            out += "'\\''";
        } else {
            out.push_back(c);
        }
    }
    out += "'";
    return out;
}

