        int len = rng() % 80;
        for (int i = 0; i < len; ++i) s.push_back(alphabet[rng() % alphabet.size()]);
        auto r = merkle_proof_from_json(s);
        if (r.ok()) {
            // 任何“成功”结果都必须满足基本不变量。
            if (r.proof.siblings.size() > 64) return 3;
        }
    }
    // 2) 对合法证明做随机变异（插入/删除/替换）：不得崩溃。
    for (int it = 0; it < 200000; ++it) {
        std::string s = valid;
        int ops = 1 + rng() % 4;
        for (int k = 0; k < ops; ++k) {
            int kind = rng() % 3;
            if (s.empty()) break;
            size_t p = rng() % s.size();
            if (kind == 0) s.insert(s.begin() + p, alphabet[rng() % alphabet.size()]);
            else if (kind == 1) s.erase(s.begin() + p);
            else s[p] = alphabet[rng() % alphabet.size()];
        }
        auto r = merkle_proof_from_json(s);
        (void)r;
    }
    // 3) 深层 / 超大输入。
    (void)merkle_proof_from_json(std::string(1000000, '['));
    (void)merkle_proof_from_json(std::string(1000000, ' '));
    std::string bigstr = "{\"version\":1,\"root\":\"";
    bigstr += std::string(100000, 'a');
    bigstr += "\"}";
    (void)merkle_proof_from_json(bigstr);
    // 4) 未变异的合法文本（无换行）和带换行变体必须成功。
    if (!merkle_proof_from_json(valid).ok()) return 1;
    if (!merkle_proof_from_json(valid + "\n").ok()) return 2;
    puts("fuzz ok");
    return 0;
}
